    ['Falzuuk']                          = { type = "Imperial Gate Guard", icon = "ImperialGateGuard.png", zones = { "Al Zahbi" }, zoneIds = { 48 }, note = "Notes:\n:*Casts Sanction on registered mercenaries (w/ Sanction Enhancements) :*Recharges Chariot Band, Emperor Band, or Empress Band. :*Sells items for Imperial Standing at appropriate rank. :*Explains Sanction, Imperial Standing, and Besieged system by choosing some available questions." },
