    ['Foudeel']                          = { type = "Chocobo Guide", icon = "ChocoboRenter.png", zones = { "Al Zahbi", "Cutscene" }, zoneIds = { 48 }, note = "Involved in Quests:\n* Give Peace a Chance\n* Three Men and a Closet\n" },
