    ['Ensetsu']                          = { type = "Ninja Unlock", icon = "Dialogue.png", zones = { "Bastok", "Port Bastok" }, zoneIds = { 236 }, note = "Starts Quests:\n* Ayame and Kaede\n\nInvolved in Quests:\n* 20 in Pirate Years\n* I'll Take the Big Box" },
