-------------------------------------------------------------------------------
-- Bastok (S) NPC's
-------------------------------------------------------------------------------
    ['1st Gold Musketeer']               = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Rolanberry Fields (S), Pashhow Marshlands (S), Grauberg (S) Bastok Markets (S)" }, zoneIds = { 91 }, note = "Notes:\nFollows Elivira. Uses Marksmanship weaponskills." },
    ['1st Iron Musketeer']               = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Rolanberry Fields (S), Pashhow Marshlands (S), North Gustaberg (S)" }, note = "Notes:\n*  Appears during Offensive Campaign Battles in Rolanberry and Pashhow, following Bartholomaus. They will cure themselves and Bartholomaus, as well as use tier III black magic on their targets. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon." },
    ['1st Legion Aidman']                = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Belfry" }, note = "Notes:\n* Spawned by an Allied Belfry erected by the Republican Army of Bastok. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter. *Capable of casting a few spells such as Diaga II, Dia II, Banish III, Banishga III, Poisona and Holy which they will use very often. *They fight with Hand-to-Hand damage and are capable of using the following weaponskills: Combo, Spinning Attack, One Inch Punch, Raging Fists and Backhand Blow. \"1st Legion\" probably indicates they are part of Legatus Berger's 1st Division/Legion." },
    ['1st Legion Mercenary']             = { type = "Campaign Battle", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Belfry" }, note = "Notes:\n* Spawned by an Allied Armored Belfry erected by the Republican Army of Bastok. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter." },
    ['1st Legion Reiter']                = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)Crawlers' Nest (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n* Appears in Campaign Battles in Bastok Markets (S) and Crawlers' Nest (S), following Else. They will cure themselves, as well as Else. *\"1st Legion\" probably indicates they are the cavalry of Legatus Berger's 1st Division/Legion." },
    ['1st Legionnaire']                  = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Grauberg (S)" }, zoneIds = { 89 }, note = "Notes:\n* Appears during Campaign Battles in North Gustaberg and Grauberg, following Maximilian. Uses Marksmanship weaponskills. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon." },
    ['2nd Legion Grenadier']             = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Battle", "Rolanberry Fields (S)" }, zoneIds = { 91 }, note = "Notes:\n* Appears in Campaign Battles at Rolanberry Fields, following Striking Bull. *\"2nd Legion\" probably indicates they are the heavy infantry of Legatus Eichberg's 2nd Division/Legion." },
    ['2nd Legionnaire']                  = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "North Gustaberg (S)" }, zoneIds = { 88 }, note = "Notes:\nParticipates in offensive Campaign Battles in North Gustaberg (S). Casts Dark Knight spells (such as Absorb-TP), but uses polearm weaponskills at least up to Skewer." },
    ['3rd Legionnaire']                  = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "North Gustaberg (S) during Campaign" }, zoneIds = { 88 } },
    ['4th Legionnaire']                  = { type = "Campaign Battle", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Varies" }, note = "Notes:\n* Appears during Campaign Battles as part of the Fourth Division Centurion unit. *In areas under allied control, they will deliver supplies to the fortifications and warp out. *In areas under beastman control, they will attempt to bomb the fortifications. *They will attempt to construct an Allied Belfry in offensive Campaign battles when Bastok's technological level allows." },
    ['7th Cohor Legionnaire']            = { type = "Campaign Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Everbloom Hollow" }, zoneIds = { 86 }, note = "Involved in Missions:\n* A Nation on the Brink (WOTG14)\n" },
    ['8th Iron Musketeer']               = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Crawlers' Nest (S), North Gustaberg (S), Bastok Markets (S), Grauberg (S)" }, note = "Notes:\nParticipates in offensive Campaign Battles in Crawlers' Nest, following Kurt. Uses Ranged Attacks and Ninjutsu." },
    ['Adelbrecht']                       = { type = "Centurion", icon = "Guard.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Starts Quests:\n* The Fighting Fourth\n\nInvolved in Missions:\n* Back to the Beginning\n" },
    ['Adelheid']                         = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Appears during Campaign Battles in Grauberg (S) and Bastok Markets (S) as the leader of the 2nd Legion Scouts. Also appears in Ruhotz Silvermines during the quest Fire in the Hole. :* Summons various status ailment \"tubes\" (e.g. Silence Tube, Stun Tube, etc.) into the battle. These Tubes inflict a status ailment on opposing forces in an area of effect. :* Casts all Tier IV spells and all spells available to a Red Mage (Dia III, Gravity, Bind, Silence, etc.) Also uses Stun and Sleepga II. :* Like most unique generals she has a distinct weapon, in her case she wields Seveneyes. :* Uses Seraph Strike for ~200 damage, and Judgment for 500+ damage, but won't naturally walk within melee range. Also uses Moonlight and Starlight. :* Uses Tabula Rasa. :* Talk: ...Heavy infantry, five columns of 200... Two 100-knight regiments... Enemy force casualties estimated at 5,000... Oh, I apologize, soldier. I've spent the past few nights preparing for a joint operation with San d'Oria's Royal Knights. :* Battle Cry: A good soldier always comes prepared. Hehehehe!" },
    ['Adelheid Sturm']                   = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n* Fire in the Hole\n" },
    ['Adelinde']                         = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"The Brilioth Estate lies in the residential area. They are certainly the most notable family of dancers in these parts. They say the only daughter, Laila, is doing her dancer training now under the strict tutelage of her mother.\"" },
    ['Adjutant (Bastok)']                = { type = "Mission Associate", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Crystal Fist I (B)\n* Crystal Fist II (B)\n* Crystal Fist III (B)\n* Crystal Fist IV (B)\n* Iron Anvil I (B)\n* Iron Anvil II (B)\n* Iron Anvil III (B)\n* Iron Anvil IV (B)" },
    ['Aged Stone, L.C.']                 = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "East Ronfaure (S)" }, zoneIds = { 81 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of East Ronfaure (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Aloysius, I.M.']                   = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "La Vaule (S)" }, zoneIds = { 85 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of La Vaule (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign." },
    ['Angry Bull (S)']                   = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"The Galkan Bridge is currently closed to prevent infiltration by beastman spies.\"" },
    ['Annabelle']                        = { type = "Campaign Evaluator", icon = "TacticalAssessment.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Annabelle provides evaluations for players aligned with the Fighting Fourth." },
