    ['Astrid, I.M.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Crawlers' Nest (S)" }, zoneIds = { 171 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Crawlers' Nest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Aurelius']                         = { zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 } },
    ['Bartholomaus']                     = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Can appear in all Campaign Battles for Bastok (S) as the leader of the 1st Iron Musketeers. :*Bartholomaus is among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon. :* Uses Circle Blade for 200-600 damage, Vorpal Blade for 1400-3200 damage, Swift Blade for 900-1700, and his own unique AoE Weapon Skill called Glory Slash for 600-1300. :* Uses Mighty Strikes (can use more than once) and Warcry (every couple minutes). :* Talk: The Republic was formed with the blood and sweat of the people. The flames of freedom must continue to light our furnaces of strength. The waters of civilization must continue to turn our wheels of ingenuity! :* Battle Cry: You barbarians will regret the day you set foot on Bastokan soil!" },
    ['Bartholomaus Krueger']             = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Quelling The Storm\n* Honor Under Fire\n* Beneath the Mask\n" },
    ['Benjamin']                         = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"The Allied Forces of Altana have been formed collectively by Jeuno and the three nations to combat the Beastmen Confederate. We've no business in an alliance with Windurst, if you ask me. Those Windurstians are not to be trusted. Am I the only one who remembers the Elshimo Campaign!?\"" },
    ['Bhio Fehriata']                    = { type = "Traveling Bard", icon = "PastEventWatcher.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Will change your Title for a fee or can give you a random title for free. *For a full list of titles, which you can get with this NPC, see Titles." },
    ['Bhoratz']                          = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Cutscene", "Grauberg (S)" }, zoneIds = { 89 }, note = "Involved in Quests:\n* Message on the Wind" },
    ['Biggorf (S)']                      = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Light in the Darkness\n* Quelling The Storm\n" },
    ['Blatherix']                        = { type = "Informant", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Light in the Darkness\n* Burden of Suspicion\n* Quelling The Storm\n" },
    ['Blazing Lizard, L.C.']             = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Jugner Forest (S)" }, zoneIds = { 82 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Jugner Forest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Blingbrix']                        = { type = "Standard Merchant", icon = "Merchant.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Blingbrix good Gobbie from Boodlix's! Boodlix's Emporium help fighting fighters and maging mages. Gil okay, okay?\"" },
    ['Bottomless Gorge']                 = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"This is the Freidrich Battery. It bears the name of President Freidrich, our great leader during the First Battle of Konschtat. The battery has been reinforced with the finest Bastokan artillery to repel the siege of the beasthordes.\"" },
    ['Christoph']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Senator Werner is adamant about having a technologically advanced military. He even goes so far as to visit the Metalworks from time to time. It seems Chief Engineer Cid is extremely busy after taking up the additional post as head of the Gunpowder Room.\"" },
    ['Clemens']                          = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"This facility is for the temporary imprisonment of beastmen prisoners of war. For your own safety, you are advised to keep your distance.\"" },
    ['Dancing Thunder, L.C.']            = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Sauromugue Champaign (S)" }, zoneIds = { 98 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Sauromugue Champaign (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Darksteel Hurricane']              = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Cut Scenes Only", "Cutscene" }, note = "Involved in Quests:\n* Quelling the Storm\n" },
    ['Derek Karst']                      = { type = "Republican Army", icon = "Dialogue.png", zones = { "Bastok (S)", "Cutscene", "Cutscenes" }, note = "Involved in Quests:\n* Storm on the Horizon\n* Fire in the Hole\n* Bonds of Mythril\n" },
    ['Detlef, I.M.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Beadeaux (S)" }, zoneIds = { 92 }, note = "Notes:\n* Bastok (S) affiliated Campaign Arbiter. Present when Bastok (S) has control of Beadeaux (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Dieter']                           = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Burden of Suspicion\n* Storm on the Horizon\n* Fire in the Hole" },
    ['Drangord (S)']                     = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Mining activities were forced to a halt when a squadron of Quadav seiged the entrance to the Palborough Mines. Not to say that mining day after day is a bag of laughs, but having no work at all is even worse. Maybe I'll volunteer for the Legion...\"" },
    ['Dunbaff']                          = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Light in the Darkness\n* Storm on the Horizon\n" },
    ['Eleonore']                         = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"I'm not quite sure why, but whenever I see a comet like that, it just puts a flutter in my chest.\"" },
    ['Elivira']                          = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:*Gold Musketeer Captain of the Department of Mining during the Crystal War. :*Shares her unique face-type with Mythril Musketeer Captain Klara. :* Can appear in all Campaign Battles for Bastok (S) as the leader of the 1st Gold Musketeers. :* Uses Split Shot for 200+ damage, Slug Shot for 1200-1400 damage, Heavy Shot for 800+ damage, and the Relic Weapon Skill Coronach for 800-1100 damage. She Weapon Skills frequently, usually attempting to self-Skillchain. :* Talk: The Metalworks' strategies are too timid for my taste. The beastmen are nothing but dominoes, waiting to be toppled. A swift, aggressive assault is the only way to victory. :* Battle Cry: A swift end is the only mercy you'll receive from me, fiends!" },
    ['Elivira Gogol']                    = { type = "Mythril Musketeer", icon = "Guard.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Gold Musketeer Captain of the Department of Mining during the Crystal War. *Shares her unique face-type with Mythril Musketeer Captain Klara. \"The Metalworks' strategies are too timid for my taste. The beastmen are nothing but dominoes, waiting to be toppled. A swift, aggressive assault is the only way to victory.\"" },
    ['Else']                             = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Appears during Campaign Battles in Crawlers' Nest (S) as the leader of the 1st Legion Reiters :* Can cast Cure IV, Paralyze II, Slow II, Bindga, Stone III, and Blizzard III. :* Uses Penta Thrust, Skewer, and Impulse Drive. :* Her attacks have additional Effect: Petrification. :* Uses Chainspell. :* Uses Oppresive Embrace :* Talk: Have you ever stopped to ponder what that comet might truly portend? I'd like to believe it is a message of hope--that soon this age of darkness will come to a close... :* Battle Cry: This is your last chance. Throw down your weapons and your life will be spared. If you refuse..." },
    ['Engelhart']                        = { type = "Quest Associate", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Better Part of Valor\n* Fires of Discontent\n* Burden of Suspicion" },
    ['Erik']                             = { type = "Notorious Monster", icon = "GoalTracker.png", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Involved in Quests:\n* Lost in Translocation\n" },
    ['Erlene']                           = { type = "Quest Giver", icon = "QuestGiver.png", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Starts Quests:\n* A Little Knowledge\n* On Sabbatical\n* Downward Helix\n* Seeing Blood-red\n" },
    ['Ernestine']                        = { type = "Quest Associate", zones = { "Bastok (S)", "Bastok Markets (S)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Burden of Suspicion" },
    ['Faltavie']                         = { type = "Map Vendor", icon = "MapDealer.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 } },
    ['Feral Moon, L.C.']                 = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Vunkerl Inlet (S)" }, zoneIds = { 83 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Vunkerl Inlet (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Field Musician Guard']             = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Pashhow Marshlands (S)" }, zoneIds = { 90 }, note = "Notes:\n* Participates in offensive Campaign Battles in Pashhow Marshlands, following Sonia. *They attack twice per combat round and occasionally Double Attack. *They can use all Hand-to-Hand weaponskills up to Howling Fist." },
    ['Field Woundpatcher']               = { type = "Campaign Battle", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S), North Gustaberg (S), Grauberg (S), Pashhow Marshlands (S), Crawlers' Nest (S), Rolanberry Fields (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:*Appears in Campaign battles along with another dispatched unit (except the 4th Legionnaire) in areas under Bastok's control; they never appear as a standalone unit. :*They will cast Blink, Phalanx, Stoneskin, Raise, and up to Protect IV, Shell IV, and Cure V on Campaign NPCs, anyone with Allied Tags on, and Beastmaster pets. Their spells seem to be on a timer, similar to Pixies. :*The selection of spells they'll cast is dependent on conditions of the Republican Army of Bastok. Their capabilities can be augmented by doing the Cut and Cauterize (B) campaign ops. :*They will not attack unless attacked. When attacked, she'll draw her club and start attacking the aggressor. This will often happen in battles with monsters that use AoE attacks (such as Wrath of Gu'Dha). :*Has a finite MP pool, as of such will actually be seen in the Command/heal stance to recover MP and HP. You will often see them /heal after all Campaign mobs nearby are defeated and Campaign still continues because another wave is on the way. :*In the event that the unit they arrived with retreats, they will remain on the battlefield and not retreat, remaining to assist anyone nearby and to fight if attacked. :*Have low defence and HP compared to other Republican Army units, as of such they wont last long when attacked. :*Uses an ability called Goddess's Shield; this enables them to cast self-targeting spells like Blink and Phalanx on allied targets." },
    ['Five Moons']                       = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Bastok Markets (S) (Cutscene only)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n* Storm on the Horizon\n* Fire in the Hole\n* Quelling the Storm\n* Honor Under Fire\n* Beneath the Mask\n* What Price Loyalty\n" },
    ['Fridolin']                         = { type = "Campaign Allegiance", icon = "AllegianceChanger.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\nWill allow those who originally aligned to Bastok's campaign and later switched to other nations' campaign to return to Bastok for a price of 300 AN and the two highest campaign medals. Recompleting The Fighting Fourth is not required, or even possible." },
    ['Friedhold']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Due to the encroaching threat of the Quadav Shieldwarriors, entry to Southern Gustaberg is currently prohibited. The republic appreciates your understanding.\"" },
    ['Gebhardt']                         = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "North Gustaberg (S)" }, zoneIds = { 88 }, note = "Involved in Quests:\n* The Fighting Fourth\n" },
    ['Gentle Tiger (S)']                 = { type = "Campaign NPC", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Starts Quests:\n* Light in the Darkness\n* Burden of Suspicion\n* Honor Under Fire\n* What Price Loyalty\n\nInvolved in Quests:\n* Fires of Discontent\n* Storm on the Horizon\n* Fire in the Hole\n* Quelling The Storm\n* Beneath the Mask\n* On Sabbatical\n" },
    ['Granite Fist, L.C.']               = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Batallia Downs (S)" }, zoneIds = { 84 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Batallia Downs (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Gray Colossus, L.C.']              = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Beaucedine Glacier (S)" }, zoneIds = { 136 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Beaucedine Glacier (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Gumbah (S)']                       = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Storm on the Horizon\n* Fire in the Hole\n" },
    ['Helmfried']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Before the onset of war, President Prien ralled the strong support of the Galkan citizenry. That was the key to his winning the election. But it seems his campaign promises of improving living standards have been complicated by the outbreak of hostilities.\"" },
    ['Herbert']                          = { type = "Quest Associate", zones = { "Bastok (S)", "Cutscene" }, note = "Involved in Quests:\n* Beneath the Mask" },
    ['Heumila']                          = { type = "Past Event Watcher", icon = "PastEventWatcher.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 } },
    ['Hinrich']                          = { type = "Campaign Information", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\nPresents information on Bastok's current Campaign strategies and intel on the other 6 forces." },
    ['Hrichter Karst']                   = { type = "President", icon = "Dialogue.png", zones = { "Bastok (S)", "Cutscene", "Cutscenes" }, note = "Involved in Quests:\n* Burden of Suspicion\n* Bonds of Mythril\n" },
    ['Invincible Shield (S)']            = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Affairs of State\n" },
    ['Isabella']                         = { type = "Survey", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Supply Commander of the Fourth Division's Seventh Cohors. *Allows Bastok affiliated players to vote on future campaign tactics. \"600 loaves of iron bread...check. 15,000 copper bullets...check. Ah-- I am sorry, soldier, but my hands are tied at the moment. Could you return at a later date?\"" },
    ['Jagaris']                          = { type = "Armor Depository", icon = "ArmorStorer.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\nStores lvl 24-60 AF, Relic, RSE and other gearsets." },
    ['Jagged Onyx, L.C.']                = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "North Gustaberg (S)" }, zoneIds = { 88 }, note = "Notes:\n* Bastok (S) affiliated Campaign Arbiter. Present when Bastok (S) has control of North Gustaberg (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Jeremias']                         = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "North Gustaberg (S)" }, zoneIds = { 88 }, note = "Involved in Quests:\n* Better Part of Valor\n" },
    ['Johann, I.M.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Eldieme Necropolis (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Karlotte']                         = { type = "Item Deliverer", icon = "ItemDeliverer.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Item Delivery services will not be available if the city is under attack. \"Do you have something you wish to send?\"" },
    ['Kasper']                           = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"When the beasthordes sieged San d'Oria, President Prien wasted no time in putting the entire republic on a wartime footing. In retrospect, it was certainly the right thing to do. If not for his unwavering leadership, we would most likely have begun the war well behind the already expanding beasthordes.\"" },
    ['Keenan']                           = { type = "ANNM Coordinator", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Starts Quests:\n* Allied Notes Notorious Monsters\n" },
    ['Kevan']                            = { type = "Sealed Container", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Trade Sealed Containers to him to receive the corresponding key item for SCNM battle." },
    ['Klara']                            = { type = "Flavor NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S) (Cutscene only)", "Cutscene" }, zoneIds = { 87 }, note = "Starts Quests:\n* Quelling the Storm\n\nInvolved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n* Storm on the Horizon\n* Fire in the Hole\n* Honor Under Fire\n* Beneath the Mask\n* What Price Loyalty\n* The Truth Lies Hid\n* Bonds of Mythril\n" },
    ['Kurt']                             = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Can appear in all Campaign Battles for Bastok (S) as the leader of the 8th Iron Musketeers. :* Uses Tachi: Enpi for 500-1200+ damage, Tachi: Jinpu for 300-1500 damage, and his own unique AoE Knockback Weapon Skill called Iainuki for 500-1000 damage. Though he does not spam his Weapon Skills, sometimes he'll self-Skillchain Iainuki to Tachi: Jinpu, making Detonation. :* Spams Shuriken for 100-400 damage. :* Talk: Move along, soldier. I have nothing to say to you. :* Battle Cry: Watch carefully, because this is the last thing you'll ever see in this life! :* He has roughly 15000 HP." },
    ['Laurentia']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"There's a mining spot in Grauberg where you can dig up some very good quality crystals. Apparently the Quadav Shieldwarriors will stop at nothing to gain control of mining resources. That's the reason for the continuing conflict between them and republic.\"" },
    ['Layton']                           = { type = "Standard Merchant", icon = "Merchant.png", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 } },
    ['Lennart']                          = { type = "Item Deliverer", icon = "ItemDeliverer.png", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Notes:\n* Item Delivery services are not available if The Eldieme Necropolis (S) is under beastman control or a campaign battle is occurring." },
    ['Lothur, I.M.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Castle Zvahl Keep (S)" }, zoneIds = { 155 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Castle Zvahl Keep (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign." },
    ['Loussaire']                        = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Starts Quests:\n* Scholar's Loafers Quest\n* Scholar's Pants Quest\n* Scholar's Gown Quest\n" },
    ['Ludwig (S)']                       = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Involved in Missions:\n* | involved in quests\n" },
    ['Ludwig Eichberg']                  = { type = "Campaign Leader", icon = "TacticalAssessment.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Affairs of State\n" },
    ['Magdalena']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"I'll admit, I wasn't sure how things would turn out when Selbina suddenly declared its independence. Senator Werner dispatched the Republican Legion and took control of the situation with such incredible speed. Even the president himself was amazed by the senator's show of skill.\"" },
    ['Marianna, I.M.']                   = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Fort Karugo-Narugo (S)" }, zoneIds = { 96 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Fort Karugo-Narugo (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Martina']                          = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Cutscene", "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Involved in Quests:\n* Fire in the Hole" },
    ['Matthias (S)']                     = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"I'm a huge fan of Laila's dancing! She's such an artist! Everyone agrees that she is a child prodigy. It's undeniable! Unfortunately, she's also famous for not signing autographs. Promise if you ever get one, you'll give it to me!\"" },
    ['Maximilian']                       = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Holds the title of 1st Division's Legatus which makes him Commander in Chief of the 1st Division/Legion of the Republican Army. :* Shares his unique face-type with Brandolf. :* Can appear in all Campaign Battles for Bastok (S) as the leader of the 1st Legionnaire squadron. :*Maximilian is among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon. :* Uses Circle Blade for 600-1100 damage, Vorpal Blade for 1500-3200 damage, and Swift Blade for 1100-2800 damage. He swings fast, with many Triple Attack and Critical hit procs. :* Uses Perfect Dodge. :* Talk: Turtle sleeps in a rocky den~'Cause he's not a citizen~Strike him down with sword and stave~Stick a blue flag in his grave~ :* Battle Cry: Ryaaaaaaaaah!" },
    ['Maximilian Berger']                = { type = "Campaign Leader", icon = "TacticalAssessment.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Affairs of State\n" },
    ['Melina']                           = { type = "Chocobo Renter", icon = "ChocoboRenter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Magna Cache I (Bastok)\n* Magna Cache II (Bastok)\n* Magna Cache III (Bastok)\n" },
    ['Millard, I.M.']                    = { type = "Sigil", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n:*Casts Sigil :*Sells items for Allied Notes (Bastok Campaign Items) at certain conditions. :*Explains the Campaign system by choosing some available questions. :*Tells you the remaining time on your current Sigil effect. For further information see Campaign Arbiter." },
    ['Minna']                            = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Through this tunnel lie the Fourth Division barracks. While far from luxurious, the rooms provide troops with a place to store their belongings, receive packages, and rest up before missions.\"" },
    ['Nicolaus']                         = { type = "Mythril Musketeer", icon = "Guard.png", zones = { "Bastok (S)", "Bastok Markets (S) (Cutscene only)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n* Storm on the Horizon\n* Fire in the Hole\n* On Sabbatical\n* Quelling the Storm\n* Honor Under Fire\n* Beneath the Mask\n* What Price Loyalty\n" },
    ['Nudara (S)']                       = { type = "Campaign NPC", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* This NPC appears in the present and can be found at Nudara \"Things sure have taken a turn for the worse around here as of late. That's why everyone is closing up shop.\"" },
    ['Offa (S)']                         = { type = "Crystal War Quest", icon = "QuestNPC.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* A Proper Burial" },
