    ['Paul']                             = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Quelling The Storm\n" },
    ['Polished Fang, L.C.']              = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Grauberg (S)" }, zoneIds = { 89 }, note = "Notes:\n* Bastok (S) affiliated Campaign Arbiter. Present when Bastok (S) has control of Grauberg (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Pondering Peak, L.C.']             = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Meriphataud Mountains (S)" }, zoneIds = { 97 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Meriphataud Mountains (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Prien']                            = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Cutscene" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Fires of Discontent\n* Burden of Suspicion\n* Fire in the Hole\n* Quelling the Storm\n* Honor Under Fire\n* What Price Loyalty\n\nInvolved in Missions:\n* Affairs of State\n" },
    ['Professor Schultz']                = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Cutscene" }, note = "Starts Quests:\n* Survival of the Wisest\n\nInvolved in Quests:\n* A Little Knowledge\n* On Sabbatical\n* Seeing Blood-red\n" },
    ['Radford']                          = { type = "Mission Associate", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Affairs of State" },
    ['Raginmund']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Quests:\n* Too Many Chefs\n* (This NPC is only present when there is no Campaign Battle.)\n" },
    ['Rainer']                           = { type = "Quest Associate", zones = { "Bastok (S)", "Cutscene" }, note = "Involved in Quests:\n* Beneath the Mask" },
    ['Red Axe']                          = { type = "Quest Associate", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Involved in Quests:\n* Beneath the Mask" },
    ['Red Canyon (S)']                   = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"Port Bastok is strictly off-limits to all but authorized personnel. However, if you wish to travel to North Gustaberg, you may use the Republic's supply causeway. Cross the bridge?\"" },
    ['Republic Supplier']                = { type = "Campaign Battle", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Battle", "Varies" }, note = "Notes:\n* Appears during an offensive campaign against Beastman territories. Up to 3 suppliers may be present at a time. *Distributes temporary items to players allied with Bastok in the battle. *Upon the depletion of their stock, these distributors will temporarily return to headquarters in order to replenish their stores. *They will take defensive action against aggressors, but during that time they will be unable to dispense items. Should they become incapacitated in the course of battle, a replacement will be dispatched after a certain amount of time has elapsed. *Item availability and quantity is directly influenced by each nation's skill and production levels." },
    ['Roaring Badger']                   = { type = "Mission Associate", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Involved in Missions:\n* Bridge Too Far I (Bastok)" },
    ['Rolf']                             = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"This here's a useful chocobo as you'll ever see. Capable of anything from battle mount to messenger chocobo!\"" },
    ['Ruediger, I.M.']                   = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Garlaige Citadel (S)" }, zoneIds = { 164 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Garlaige Citadel (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Rusted Musket']                    = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n\"At the battle of Vunkerl Inlet, the Republican Legion's Third Division encountered a gigas raiding party approaching by sea. The fiends eventually made landfall, but their advance was stopped cold by the brilliant tactics of Legatus Invincible Shield. No doubt his military genius will become the stuff of legend!\"" },
    ['Scarred Shark']                    = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Starts Quests:\n* Hammering Hearts\n" },
    ['Shenni']                           = { type = "Trust Coordinator", icon = "Trust.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Special Event" }, zoneIds = { 87 }, note = "Notes:\n* Shenni only appears at ({{Location Tooltip|area=Bastok Markets (S)|pos=F-9" },
    ['Silke']                            = { type = "Standard Merchant", icon = "Merchant.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n*  Remains available during Campaign Battles." },
    ['Sonia']                            = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Uses Trance. :* Appears during Campaign Battles in Pashhow Marshlands (S) as the leader of the Field Musician Guard. :* Uses all Hand-to-Hand weaponskills including Asuran Fists. :* Very low delay attacks and very high critical hit rate with an Additional Effect: Stun. :* Sonia will use all Dancer abilities, including Reverse Flourish if needed. :* Uses a dance called 'Reverie Frolic', which gives all hostile targets in range the effect of Dia, Accuracy Down, and Magic Accuracy Down. :* Talk: You look like you've seen better days, soldier. Let me guess, it's the war that's bringing you down. What you need is a little music in your life! :* Battle Cry: To your seats, boys! The show is about to begin!" },
    ['Stray Boar, L.C.']                 = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Pashhow Marshlands (S)" }, zoneIds = { 90 }, note = "Notes:\n* Bastok (S) affiliated Campaign Arbiter. Present when Bastok (S) has control of Pashhow Marshlands (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Striking Bull']                    = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)", "Battle" }, zoneIds = { 87 }, note = "Notes:\n:* Appears during Campaign Battles in Rolanberry Fields (S) as captain of the 2nd Legion Grenadiers. :* Has a very low attack delay. :* Stands back and spams Mistral Axe for 400-800 damage; however, sometimes he ends up standing there and not doing anything. He can also use Smash Axe for 200+ damage, Gale Axe for 200+ damage, Avalanche Axe for 200+ damage, Calamity for 300-600 damage, and Decimation for up to 500 damage. :* Uses Bloody Tomahawk ability approximately every 20 seconds for 100-500 damage. :* Talk: If it weren't for the Galkan heavy infantry, this nation wouldn't last a month against the turtlebacks. And what thanks do we get? A handful of stale army biscuits! :* Battle Cry: Ahahahaha! My hand slipped! :* For some reason, it seems difficult/impossible to see Striking Bull's damage against enemy leaders." },
    ['Tenacious Fool, L.C.']             = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "West Sarutabaruta (S)" }, zoneIds = { 95 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of West Sarutabaruta (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Thorben']                          = { type = "Quest Giver", zones = { "Bastok (S)", "Batallia Downs (S)" }, zoneIds = { 84 }, note = "Starts Quests:\n* Lost in Translocation" },
    ['Timid Scorpion, L.C.']             = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Xarcabard (S), (?-?)" }, zoneIds = { 137 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Xarcabard (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Turbulent Storm']                  = { type = "Pixie Recruiter", icon = "Dialogue.png", zones = { "Bastok (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Involved in Quests:\n* The Fighting Fourth\n\nInvolved in Missions:\n* Back to the Beginning\n" },
    ['Ulbrecht']                         = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Bastok (S)", "Cutscene" }, note = "Involved in Quests:\n* A Little Knowledge\n* On Sabbatical\n* Downward Helix\n* Seeing Blood-red\n" },
    ['Volker (S)']                       = { type = "Mythril Musketeer", icon = "Guard.png", zones = { "Bastok (S)", "Cutscene", "Cutscenes" }, note = "Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n* Storm on the Horizon\n* Fire in the Hole\n* Quelling the Storm\n* Honor Under Fire\n* What Price Loyalty\n* The Truth Lies Hid\n* Bonds of Mythril" },
