    ['Waldemar, I.M.']                   = { type = "Allied Campaign Assessment", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n# You can have him Retrace you if you are not already in your nation of allegiance in the past." },
    ['Wayward Echo, L.C.']               = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Bastok (S)", "Rolanberry Fields (S)" }, zoneIds = { 91 }, note = "Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Rolanberry Fields (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Weldon']                           = { type = "Item Deliverer", icon = "ItemDeliverer.png", zones = { "Bastok (S)", "Bastok Markets (S)" }, zoneIds = { 87 }, note = "Notes:\n* Item Delivery services will not be available if the city is under attack. \"I am here to help with all your parcel delivery needs.\"" },
