    ['Pohka Chichiyowahl']               = { type = "Standard Merchant", icon = "Merchant.png", zones = { "Bibiki Bay - Purgonorgo Isle", "Outland" }, zoneIds = { 4 }, note = "Notes:\nSells Fishing Equipment. ;Prices are determined by Windurst Fame. Sells: * Fastwater Fishing Rod Price: 1238-1667 gil * Single Hook Fishing Rod Price: 11845-15398 gil * Antidote Price: 290-656 gil" },
