    ['Afdeen']                           = { type = "Battlefield Transport", icon = "Dialogue.png", zones = { "Jeuno", "Upper Jeuno" }, zoneIds = { 244 }, note = "Notes:\nA student of the great mage Abdhaljs, he handles transport to and the use of Abdhaljs Isle-Purgonorgo (where Brenner is played). He (as well as the Marshal behind him) will handle all Brenner-related affairs, including distribution of the Brenner Bluebook & Brenner Blackbook." },
    ['Ajahkeem']                         = { type = "Adventuring Fellow", icon = "Dialogue.png", zones = { "Jeuno", "Ru'Lude Gardens" }, zoneIds = { 243 }, note = "Notes:\n* Exchanges fellow points for items for yourself and your fellow. *To gain access to fellow points, equip your Signal Pearl and speak to Luto Mewrilah in Upper Jeuno (G-8) for a cutscene. *Go to G-9 in Ru'Lude Gardens, next to the Rendezvous Point, and speak with Ajahkeem for a second cutscene. This may not trigger until some level of bond between zero and the amount required for Past Reflections is obtained{{verification" },
    ['Ajithaam']                         = { type = "Mercenary Teleport", icon = "WarpNPC.png", zones = { "Jeuno", "Upper Jeuno" }, zoneIds = { 244 }, note = "Starts Quests:\n* Lure of the Wildcat (Jeuno)\n" },
    ['Akamafula']                        = { type = "Tenshodo Merchant", icon = "TenshodoMerchant.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 } },
    ['Akta']                             = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Jeuno", "Ru'Lude Gardens" }, zoneIds = { 243 }, note = "Notes:\nDialog: A mighty fine palace, this is. Why, it's like a castle in the clouds! I'm so glad I came all this way to see it.Oh, now where'd the wife head off to? I suppose she'll show up if I stay put here." },
    ['Albiona']                          = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Jeuno", "Ru'Lude Gardens" }, zoneIds = { 243 }, note = "Involved in Quests:\n* Lure of the Wildcat (Jeuno)\n" },
    ['Aldo']                             = { type = "Tenshodo Chief", icon = "Dialogue.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 }, note = "Involved in Quests:\n* Mirror Images\n* Shadows of the Departed\n* Apocalypse Nigh\n\nInvolved in Missions:\n* San d'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Zilart Mission 2: Welcome t'Norg\n* Zilart Mission 8: Return to Delkfutt's Tower\n* Zilart Mission 9: Ro'Maeve\n* Zilart Mission 13: The Gate of the Gods\n* Zilart Mission 16: The Celestial Nexus\n* Zilart Mission 17: Awakening\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 3-4: Tending Aged Wounds\n* A Crystalline Prophecy (Mission)\n* A Shantotto Ascension (Mission): Sugar-coated Subterfuge\n" },
    ['Alrauverat']                       = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 }, note = "Notes:\n;Notes for all characters: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Mission-Rank bar of the character's appropriate Nation (the red bar at the character's profile) :*Sells items for Conquest Points of the character's appropriate Nation (Items for Bastok / Items for San d'Oria / Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Explains the Conquest system by choosing some available questions. For further information see Conquest Overseer." },
    ['Amalasanda']                       = { type = "Tenshodo Merchant", icon = "TenshodoMerchant.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 }, note = "Notes:\n:Hours: Always open. :No longer closed on Earthsday. :Prices are based on your Tenshodo reputation." },
    ['Amhu Sabaroleka']                  = { type = "Citizen", icon = "Dialogue.png", zones = { "Lower Jeuno" }, zoneIds = { 245 } },
    ['Anneliese']                        = { zones = { "Jeuno", "Port Jeuno" }, zoneIds = { 246 } },
