    ['Appollonia']                       = { type = "Weather Reporter", icon = "WeatherChecker.png", zones = { "Jeuno", "Upper Jeuno" }, zoneIds = { 244 }, note = "Notes:\nChecks weather for the following locations: :*Valkurm Dunes :*Jugner Forest :*Batallia Downs :*Pashhow Marshlands :*Rolanberry Fields :*Meriphataud Mountains :*Sauromugue Champaign :*The Sanctuary of Zi'Tah :*Qufim Island :*Jeuno" },
