    ['Chatnachoq']                       = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 }, note = "Notes:\n* Item exchange NPC for the Moblin Maze Mongers and Goldagrik's secretary. Players trade Moblin Marbles obtained through player mazes for additional Maze Tabulas, Maze Vouchers, Maze Runes, and even equipment. *Unwanted Maze Runes may be traded to Chatnachoq for 4-8 marbles." },
