    ['Momiji']                           = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Jeuno", "Lower Jeuno" }, zoneIds = { 245 }, note = "Notes:\nTo anyone who listens to her, Momiji recounts her youth spent with her lover, whom she describes as a shy, quiet boy. She will then remark that it is only the perspective of old age that has taught her the importance of love. Then, she will mention that her husband is well: so full of life that she doesn't know what to do. It is implied that her husband is not her remembered lover, and that she regrets a decision of her youth. She wears Maat's Cap, a hat which is also worn by Degenhard (and which is awarded to any player who defeats Maat in every job.) Articles in the Vana'diel Wind have described Maat and Degenhard as long-time rivals who once trained at the same dojo. Perhaps Mojimi is Maat's wife; perhaps Degenhard is the lost lover of her youth (although both Maat and Degenhard could be described as \"full of life.\")" },
    ['Monberaux']                        = { type = "Physician", icon = "Dialogue.png", zones = { "Jeuno", "Upper Jeuno" }, zoneIds = { 244 }, note = "Involved in Quests:\n* The Lost Cardian\n* Regaining Trust\n* Save the Clock Tower\n* The Kind Cardian\n\nInvolved in Missions:\n* Bastok Mission 3-3: Jeuno\n* Windurst Mission 3-3: A New Journey\n* San d'Oria Mission 3-3: Appointment to Jeuno\n* Promathia Mission 1-1: The Rites of Life\n* Promathia Mission 3-5: Darkness Named\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen's Path)\n" },
    ['Monisette']                        = { type = "Artifact Upgrades", icon = "Dialogue.png", zones = { "Jeuno", "Port Jeuno" }, zoneIds = { 246 }, note = "Notes:\n*  Stores chapters of Rem's Tale 1-10 for players. You may trade multiple types of chapters all at once to store them in one transaction. * Upgrades Artifact Armor/Artifact Armor +1 to Reforged Artifact Armor (Item Level 109). * Upgrades Reforged Artifact Armor to Reforged Artifact Armor +1 (Item Level 119). * Upgrades Relic Armor/Relic Armor +1 to Reforged Relic Armor (Item Level 109). * Upgrades Reforged Relic Armor to Reforged Relic Armor +1 (Item Level 119). * Upgrades Empyrean Armor to Reforged Empyrean Armor (Item Level 109). * Upgrades Reforged Empyrean Armor to Reforged Empyrean Armor +1 (Item Level 119). * When upgrading armor, {{PAGENAME" },
