    ['Addison, C.A.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "West Sarutabaruta (S)" }, zoneIds = { 95 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of West Sarutabaruta (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Allied Armored Belfry']            = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Varies" }, note = "Notes:\n* Set up by members of the Allied Forces of Altana in an enemy area when technology levels reach an unknown threshold. The groups that set them up are involved with supplies/sabotage. :*Spawns reinforcements that attack fortifications, depending on which force installed it: :*Bastokan Forces: 1st Legion Mercenary :*San d'Orian Forces: Royal Esquire :*Windurstian Forces: Cardian Prototype :*Northland Forces: Scylla Brigade Elite :*Reinforcements spawn every 30-60 seconds. :*Every so often a group of support NPCs will enter the battle and repair the Allied Belfry, restoring a portion of its HP. *Cannot be cured." },
    ['Allied Belfry']                    = { type = "Campaign Battle Ally", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Varies" }, note = "Notes:\n* Set up by members of the Allied Forces of Altana in an enemy area when technology levels reach an unknown threshold. The groups that set them up are involved with supplies/sabotage. :*Spawns reinforcements that attack fortifications, depending on which force installed it: :*Bastokan Forces: 1st Legion Aidman :*San d'Orian Forces: Royal Banneret :*Windurstian Forces: Wildcat Vanguard :*Northland Forces: Scylla Brigade Officer :*Reinforcements spawn every 30-60 seconds. :*Every so often a group of NPC's will enter the battle and cure the Allied Belfry, restoring a portion of its HP. *Cannot be cured." },
    ['Amaliya, C.A.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "The Eldieme Necropolis (S)" }, zoneIds = { 175 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of The Eldieme Necropolis (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Barnett, C.A.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Pashhow Marshlands (S)" }, zoneIds = { 90 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Pashhow Marshlands (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Kearney, C.A.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Meriphataud Mountains (S)" }, zoneIds = { 97 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Meriphataud Mountains (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Koh Lenbalalako (S)']              = { type = "Cutscene NPC", icon = "Cutscene.png", zones = { "Jeuno (S)" }, note = "Involved in Quests:\n* Sins of the Mothers\n* Manifest Destiny" },
    ['Marius, C.A.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Sauromugue Champaign (S)" }, zoneIds = { 98 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Sauromugue Champaign (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },
    ['Scarlette, C.A.']                  = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Southern San d'Oria (S)" }, zoneIds = { 230 }, note = "Notes:\n* Jeuno affliated Campaign Arbiter. *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign *You are only allowed Teleportation to areas that you have physically visited. * Costs: ** 20 Allied Notes Areas controlled by your Affiliated Country. ** 40 Allied Notes Areas non-Beastmen controlled adjacent to your home country. ** 50 Allied Notes Areas non-Beastmen controlled not adjacent to your home country. ** 80/90 Allied Notes Areas that are Beastmen controlled. *She cannot teleport you to Beastman Strongholds (Castle Oztroja (S), La Vaule (S), Beadeaux (S), Castle Zvahl Baileys (S), Castle Zvahl Keep (S), Throne Room (S))" },
