    ['Wenonah, C.A.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jeuno (S)", "Windurst Waters (S)" }, zoneIds = { 94 }, note = "Notes:\n* Jeuno affliated Campaign Arbiter in Windurst Waters (S) *Offers Campaign Information, Campaign , Teleportation *Campaign Sword in front of name during Campaign *She cannot teleport you to Beastman Strongholds (Castle Oztroja (S), La Vaule (S), Beadeaux (S), Castle Zvahl Baileys (S), Castle Zvahl Keep (S), Throne Room (S))" },

