    ['Alexius']                          = { type = "Quest Associate", zones = { "Jugner Forest" }, zoneIds = { 104 }, note = "Involved in Quests:\n* A Purchase of Arms\n* Sin Hunting" },
    ['Ardrick']                          = { type = "Pulse Exchange", icon = "Merchant.png", zones = { "Jugner Forest" }, zoneIds = { 104 }, note = "Notes:\nProvides players with assistance with Voidwatch operations or item issuance. *Ask a bunch of questions *Purchase Phase Displacers for 20,000 gil, which can be used to obtain {{KeyItem" },
    ['Bubchu-Bibinchu, W.W.']            = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Jugner Forest", "Outland", "Windurst" }, zoneIds = { 104 }, note = "Notes:\nAppears, when Norvallen is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest :*Accepts Garrison starting item Jade Cryptex ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Chaplion, R.K.']                   = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Jugner Forest", "Outland", "San d'Oria" }, zoneIds = { 104 }, note = "Notes:\nAppears, when Norvallen is under weekly conquest-control by San d'Oria ;Notes for characters only with San d'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest :*Accepts Garrison starting item Jade Cryptex ;Notes for characters only without San d'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Geruru, W.W.']                     = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Jugner Forest", "Outland", "Windurst" }, zoneIds = { 104 }, note = "Notes:\nAppears, when Norvallen is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Mionie']                           = { type = "Outpost Vendor", zones = { "Jugner Forest", "Outland" }, zoneIds = { 104 }, note = "Notes:\nAppears when Norvallen is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader's current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil", info = "Appears when Norvallen is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader's current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil" },
    ['Perevie']                          = { type = "Armor Depository", icon = "ArmorStorer.png", zones = { "Jugner Forest" }, zoneIds = { 104 }, note = "Notes:\nArmor Storer for a Ballista Event only." },
    ['Taumiale, R.K.']                   = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Jugner Forest", "Outland", "San d'Oria" }, zoneIds = { 104 }, note = "Notes:\nAppears, when Norvallen is under weekly conquest-control by San d'Oria ;Notes for characters only with San d'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest ;Notes for characters only without San d'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },

-------------------------------------------------------------------------------
-- Jugner Forest (S) NPC's
-------------------------------------------------------------------------------
    ['Auroral Alicorn']                  = { type = "New Year Event", icon = "Event.png", zones = { "Jugner Forest (S)" }, zoneIds = { 82 }, note = "Notes:\n* If its horn is currently broken, when the zone becomes engaged in a campaign battle, it will run away. *Soultrapper can be used on Auroral Alicorn. *Checks as Impossible to Gauge. *Has movement speed equal to Dark Ixion. Auroral Alicorn is known to use the following abilities: *Uses Scintillant Lance which deals 1000-1200 light-based Cone Attack. *Uses Grace of Hera that grants Regen and removes harmful status effects from everyone in the vicinity. *Uses Acheron Kick which deals 300~ damage AoE Knockback. *Uses Rampant Stance which rears up and damages targets with the possibility of inflicting Weight, Stun, and Aspir. Maruna-Kurina's Notes: Current taxonomy teaches us that at presentaru, the monoceros family contains few known specimens. Those that are classified exhibit great horn spire-wires jutting from their majestic heads, and are either born of light, or of darkness. An influx of eyewitness accounts in recent days all point to the undeniable existence of the beastaru named Dark Ixion. Tempered like a storm and ever wary, both allies and beastman alike tend to keep their distance. The other is dubbed Auroral Alicorn and exhibits a brilliantaru shade of white and a calm, gentle demeanor. The two couldn't be more dissimilar-wimilar. Though almost never seen in the wild prior to the war, Auroral Alicorn has recently been sighted in Jugner Forest, some say nursing wounds. How to Influence: *Alicorn has a passive DoT when its horn is broken. It cannot be dispelled, but he can be cured to regain his HP. The message \"The creature whinnies contentedly.\" appears when cured. *Noticed the whinnies contently message appears on first cure if you zone (i.e. Recall-Jugner) between cures. Can still say message again after some repeated curing." },
    ['Emmah Laali, M.C.']                = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jugner Forest (S)", "Windurst (S)" }, zoneIds = { 82 }, note = "Notes:\n* Windurst (S) affiliated Campaign Arbiter. Present when Windurst (S) has control of Jugner Forest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign." },
    ['Gold Badger Esquire']              = { type = "Campaign Battle", icon = "CampaignArbiter.png", zones = { "Jugner Forest (S)", "San d'Oria (S)" }, zoneIds = { 136 }, note = "Notes:\n:*Appears during Campaign Battles as part of the Gold Badger Esquire unit. :*In areas under allied control, they will deliver supplies to the fortifications and warp out. :*In areas under beastman control, they will attempt to bomb the fortifications. :*They will attempt to construct an Allied Belfry in offensive Campaign battles when San d'Oria's technological level allows. :*The Gold Badgers will not engage the enemy unless they are intercepted." },
    ['Helmyre']                          = { type = "Chocobo Renter", icon = "ChocoboRenter.png", zones = { "Jugner Forest (S)", "Outland" }, zoneIds = { 82 }, note = "Notes:\n* Must be level 20, have a Chocobo License,and be affiliated with one of the armies of the three nations to be eligible to rent a Chocobo. *Rental fees will be charged in Allied Notes rather than gil." },
    ['Larkin, C.A.']                     = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jugner Forest (S)" }, zoneIds = { 82 }, note = "Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Jugner Forest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign *Located in the NW corner of (I-8)" },
    ['Roiloux, R.K.']                    = { type = "Campaign", icon = "CampaignArbiter.png", zones = { "Jugner Forest (S)", "San d'Oria (S)" }, zoneIds = { 136 }, note = "Notes:\n* San d'Oria affiliated Campaign Arbiter. Present when San d'Oria has control of Jugner Forest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign" },

