    ['Butsutsu, W.W.']                   = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "North Gustaberg", "Windurst" }, zoneIds = { 106 }, note = "Notes:\nAppears, when Gustaberg is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Gustaberg Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Ennigreaud, R.K.']                 = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "North Gustaberg", "San d'Oria" }, zoneIds = { 106 }, note = "Notes:\nAppears, when Gustaberg is under weekly conquest-control by San d'Oria. ;Notes for characters only with San d'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Gustaberg Supplies for finishing Supply Quest :*Accepts Garrison starting item Darksteel Engraving ;Notes for characters only without San d'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Kuleo']                            = { type = "Outpost Vendor", zones = { "North Gustaberg", "Outland" }, zoneIds = { 106 }, note = "Notes:\nAppears when Gustaberg is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader's current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil", info = "Appears when Gustaberg is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader's current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil" },
    ['Kuuwari-Aori, W.W.']               = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "North Gustaberg", "Windurst" }, zoneIds = { 106 }, note = "Notes:\nAppears, when Gustaberg is under weekly conquest-control by Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Gustaberg Supplies for finishing Supply Quest :*Accepts Garrison starting item Darksteel Engraving ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Quellebie, R.K.']                  = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "North Gustaberg", "San d'Oria" }, zoneIds = { 106 }, note = "Notes:\nAppears, when Gustaberg is under weekly conquest-control by San d'Oria. ;Notes for characters only with San d'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Gustaberg Supplies for finishing Supply Quest ;Notes for characters only without San d'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },

