    ['Felicific Buffalo']                = { type = "Event NPC", icon = "Event.png", zones = { "North Gustaberg, South Gustaberg, East Ronfaure, West Ronfaure, East Sarutabaruta, West Sarutabaruta", "Special Event" }, note = "Notes:\nA buffalo found roaming in the areas outside of all three starting cities which is followed by two to three Rancher NPCs. Rancher NPCs mention the opening of the Buffalo Bonanza Ranch in Jeuno." },
    ['Rancher']                          = { type = "Event NPC", icon = "Event.png", zones = { "North Gustaberg, South Gustaberg, East Ronfaure, West Ronfaure, East Sarutabaruta, West Sarutabaruta", "Special Event" }, note = "Notes:\n* Part of the staff from Buffalo Bonanza Ranch. *Trade items to receive buffs or items that are used in Happy New Year 2009, or any Happy New Year thereafter. *They are always on the move, and they like to follow the current event Chinese zodiac animal around the area. Wide Scan and mounts are useful for locating and running them down." },

