    ['Cecilia']                          = { type = "Event NPC", icon = "Event.png", zones = { "Northern San d'Oria", "Special Event" }, zoneIds = { 231 }, note = "Notes:\nCecilia is the lead dancer of the Dancing Trio Cream Puff. She is capable of draining the life force of others through her dance moves, causing paralysis. left|thumb|Cecilia during the 2012 festival" },
    ['Celestia']                         = { type = "Event NPC", icon = "Event.png", zones = { "Northern San d'Oria", "Special Event" }, zoneIds = { 231 }, note = "Notes:\nCelestia is the lead dancer of the Dancing Trio Cream Puff. She is capable of draining the life force of others through her dance moves, causing paralysis. left|thumb|Celestia during the 2012 festival" },
    ['Chapal-Afal, W.W.']                = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Notes:\n;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Windurst Mission-Rank bar (the red bar at the character's profile) :*Sells items for Conquest Points (Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations (Items for Bastok / Items for San d'Oria) at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Explains the Conquest system by choosing some available questions. ;Notes for characters only without Windurst as current Allegiance: :*Doesn't offer any function For further information see Conquest Overseer." },
