    ['Taurette']                         = { type = "Riding the Clouds", icon = "QuestNPC.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Involved in Quests:\n* Riding on the Clouds\n" },
