    ['Trisvain']                         = { type = "HTMB Vendor", icon = "Merchant.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Notes:\nSells key items required for High-Tier Mission Battlefields. See the Phantom Gems page for individual requirements" },
    ['Uka Totlihn']                      = { type = "Event NPC", icon = "Event.png", zones = { "Northern San d'Oria", "Special Event" }, zoneIds = { 231 } },
    ['Ullegore']                         = { type = "Event NPC", icon = "Event.png", zones = { "Northern San d'Oria", "Special Event" }, zoneIds = { 231 }, note = "Notes:\nleft|180px|thumb|Ullegore's Elvaan form A long, long time ago, on a starry night different from no other, a lone meteorite fell from the bejeweled sky unbeknownst to the slumbering denizens of Vana'diel. From the superheated core of this extraterrestrial rock emerged an entity of unadulterated evil?the physical manifestation of darkness itself. The name of this twisted being was Ullegore. His sole purpose: the complete and utter eradication of joy and jubilance from the face of the world." },
    ['Ulycille']                         = { type = "Smithing Support", icon = "Dialogue.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Notes:\n* Gives recipes, and Advanced Synthesis Image Support for Woodworking." },
    ['Vamorcote']                        = { type = "Quest Giver", icon = "QuestGiver.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Starts Quests:\n* The Setting Sun" },
    ['Vavegallet']                       = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 }, note = "Notes:\n\"Hrmm... You look like another adventurer obsessed with shining swords and gleaming shields. Am I wrong?\" \"Well, the hallmark of an adventurer is a richly-decorated domicile. Really, you must visit the furniture shop!\"" },
    ['Vichuel']                          = { type = "Regional Vendor", icon = "RegionalVendor.png", zones = { "Northern San d'Oria", "San d'Oria" }, zoneIds = { 231 } },
