    ['Zandjarl']                         = { type = "Pankration Item Merchant", zones = { "Pankration", "The Colosseum" }, zoneIds = { 71 }, note = "Notes:\nZandjarl sells wares related to Pankration and where you convert Imperial Currency into Jetton, currency for Pankration. Jettons: Zandjarl will convert Imperial currency into Jettons: {{:Jetton", info = "Zandjarl sells wares related to Pankration and where you convert Imperial Currency into Jetton, currency for Pankration. ==Jettons== Zandjarl will convert Imperial currency into Jettons: ==Wares== Zandjarl will allow people without sufficient Jettons to view his wares: ===2 Jettons=== * A Soultrapper * 12 blank soul plates ===500 Jettons=== * A Soultrapper 2000 * 12 blank high-speed soul plates ===5000 Jettons=== * Zoraal Ja's Helm * Dartorgor's Coif * No.3's Garland * Cacaroon's Hood" },
