    ['Farmaoquaix']                      = { type = "Special Event Coordinator", icon = "SpecialEventCoordinator.png", zones = { "Port San d'Oria", "San d'Oria" }, zoneIds = { 232 }, note = "Notes:\nAppeared during the 2004 Starlight Celebration event." },
