    ['Chapa-Cha']                        = { type = "Residential Guard", icon = "Guard.png", zones = { "Port Windurst", "Windurst" }, zoneIds = { 240 }, note = "Notes:\n\"Beyond this gateway is the Windurst residential area, where you can stay in a Mog House or Rent-a-Room. If you need to hear an explanation, that's Boronene job. So pluck up the courage, and ask Boroene over there for all you need to knowy-wowy.\"" },
