    ['Bouncebix']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* In Actualization Team maze he lost his key and asks you to go find it or make him a new one. Once you get it to him, he will open up the Well of Passage behind him." },
    ['Chaperix']                         = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\nGoblin NPC that you help level in Moblin Maze Mongers Maze Voucher 05" },
    ['Fetchafox']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Lost his Goblin Die in the Well of Passage behind him. Asks you to retrieve it for him." },
    ['Findaflok']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\nGoblin NPC that must be rescued in Moblin Maze Mongers Maze Voucher 05. Will cast PLD spells and uses Invincible when HP gets low." },
    ['Slayalox']                         = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Asks you to kill 3 Dinky Worm's for her, then 5 Dinky Beetle's, then 10 Dinky Spider's. Rewarding you after completing each one." },
    ['Smashlix']                         = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Tells you to destroy all of the Reinforced Crates found in the Well of Passage behind him." },
    ['Sonchostiq']                       = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 } },
    ['Switchlox']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Will change the job of Chaperix to either \"Walloper\", \"Spellslinger\" or \"Barrager\". **\"Walloper\" requires the temp items Body Boost and Strength Potion. **\"Spellsplinger\" requires the temp items Wizard's Drink and Intelligence Potion. **\"Barrager\" requires the temp items Agility Potion and Dexterity Potion. *Provides the quest Ultimate Technique which can be activated after Chaperix has reached level 20 and the Maze Rune 102 has been placed on the Maze Tabula." },
    ['Tempatriq']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Will make you the key Bouncebix asks for after bringing him a Bronze ingot and silver beastcoin. **Depending on the job of Chaperix, he will ask for different ingredients to upgrade your weapon to a maximum of two times. The items requested are temp items and available in Smashlix's tunnel. ***As \"Walloper\" your first upgrade will cost you an Iron ore. Your second upgrade will need Darksteel ore and mythril beastcoin." },
    ['Vendastox']                        = { type = "Moblin Maze Mongers", icon = "GoalTracker.png", zones = { "Ruhotz Silvermines" }, zoneIds = { 93 }, note = "Notes:\n* Used in Actualization Team maze to purchase temporary items for Chaperix to use." },

