    ['Raminel']                          = { type = "Riding the Clouds", icon = "QuestNPC.png", zones = { "San d'Oria", "Southern San d'Oria Runs a path through" }, zoneIds = { 136 }, note = "Involved in Missions:\n* Riding on the Clouds\n" },
