    ['Ricaldo']                          = { type = "Airship Schedule", icon = "AirshipTravelAgent.png", zones = { "San d'Oria", "San d'Oria-Jeuno Airship" }, zoneIds = { 136 }, note = "Notes:\nWill report how long until the Airship arrives at its destination." },
