    ['Joyous Alicorn']                   = { type = "New Year Event", icon = "Event.png", zones = { "Special Event", "West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island" }, zoneIds = { 100, 101, 102, 103, 104, 105, 106, 107, 108, 109, 110, 111, 114, 115, 116, 117, 118, 119, 120, 125 }, note = "Notes:\nFollows Jubilant Alicorn, which is the only member of the procession with which interaction is possible. It is preceded by Jubilant Alicorn and proceeded by Joyful Alicorn and Mirthful Ixion." },
    ['Jubilant Alicorn']                 = { type = "New Year Event", icon = "Event.png", zones = { "Special Event", "West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island" }, zoneIds = { 100, 101, 102, 103, 104, 105, 106, 107, 108, 109, 110, 111, 114, 115, 116, 117, 118, 119, 120, 125 }, note = "Notes:\nTrade ordinary items one at a time (such as arrows, crossbow bolts, bullets, or ninja tools) to any Jubilant Alicorn to receive special items such as the monstrosity item Ake-Ome Spirit, which unlocks the monipulator form New Year Mandragora (MON). It is proceeded by Joyous Alicorn, Joyful Alicorn, and Mirthful Ixion, and roams the entire zone. It is the leader of the procession and the largest of the four." },
