-------------------------------------------------------------------------------
    ['Abby Jalunshi']                    = { type = "MogHouse Watcher", icon = "Dialogue.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nChecking Abby_Jalunshi will start a conversation with her about Mog Houses. She give you 2 options to start- : *Nothing in General : *Ask for an explanation on Mog houses. If you choose the \"Nothing in General option, she will just say: \"Oh Well, Your Loss\" and turn away. If you choose the Other option she says: \"A mogHouse is your own personal apartment room provided for your convienience. Within your MogHouse you can store items, change jobs, and heal up any HP or MP" },
    ['Aja-Panja']                        = { type = "Tutorial", icon = "TutorialNPC.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nUpon checking Aja Panja you will recieve the following diologue: :* If you want to learn how to craft bone into something useful, then you should study with us here at the Boneworker's Guild!" },
    ['Ajen-Myoojen']                     = { zones = { "Windurst", "Windurst Waters map = North|F-4" }, zoneIds = { 238 } },
