    ['Amagusa-Chigurusa']                = { type = "Quest Associate", zones = { "Windurst", "Windurst Waters map = North|G-9" }, zoneIds = { 238 }, note = "Involved in Quests:\n* Lure of the Wildcat (Windurst)" },
    ['Ambrosius']                        = { type = "Quest Giver", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Starts Quests:\n* The Postman Always K.O.s Twice" },
