    ['Angelica']                         = { type = "Quest Giver", icon = "QuestGiver.png", zones = { "Windurst", "Windurst Waters map = North|F-10 \"Rarab Tail Hostelry\" \"2? floor = Hostelry room #1\"" }, zoneIds = { 238 }, note = "Starts Quests:\n* A Pose by Any Other Name\n\nInvolved in Quests:\n* A Question of Taste\n* Picture Perfect\n* Starlight Celebration 2008" },
    ['Anillah']                          = { type = "Synthesis Support", icon = "GuildMerchant.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nAnillah is one of two workers who provides free synthesis support for clothcrafting in Windurst. Speaking with her will raise your clothcrafting skill ever so slightly, and give you a better chance at successful synths. After speaking with her however, you may not ask any other NPC for synthesis support until the one she has given you has worn away. Anillah is also in charge of the low-level recipe list; if you ask her about recipes, she will tell you any recipe that is below your current skill level." },
    ['Anini']                            = { zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 } },
    ['Anja-Enja']                        = { type = "Adventurer's Assistant", icon = "AdventurersAssistant.png", zones = { "Windurst", "Windurst Waters" }, zoneIds = { 238 }, note = "Notes:\nOffers Directions Around Town: :Hiya! Are you lost or something? If you're in trouble, Anja-Enja's here to helpy-welpy! :*\"Nothing right now.\": Well, if you ever need help, feel free to ask one of us guards. Helping out people in need is the calling of us guards in Windurst Waters's \"North Winds\" troupey-woupey. :*\"Where are we?\": This is the Windurst Waters district. Just north of here are the Opistery, the Aurastery, and a general goods store. South of here are the Rhinostery and the hatter's. :*\"How to leave town.\": The quickest way to leave town from here is Odin's Gate, which takes you out to West Sarutabaruta. Head north and pass through the archway of the Opistery's Library of Magic. Then go over the bridge until you get to the northern gatehouse. (That's where we guards of Windurst Waters meet, you know?) Head through the gate and you'll find yourself outside in West Sarutabaruta. :*\"Where's the residential area?\": Windurst's residential area is northeast of here. To get there, first head north and cross the bridge to the east that leads to the Aurastery and Windurst Walls. On the way, you'll come across a Cardian automaton guard. Turn right when you see him and you'll easily find your way there." },
    ['Aora-Uora']                        = { zones = { "Windurst", "Windurst Waters map = North|G-7" }, zoneIds = { 238 } },
    ['Apururu']                          = { type = "Manustery Minister", icon = "Dialogue.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Starts Quests:\n* Can Cardians Cry?\n* Trust: Ajido-Marujido\n\nInvolved in Quests:\n* Making Amens!\n* Legendary Plan B\n* The Kind Cardian\n\nInvolved in Missions:\n* Windurst Mission 1-1: The Horutoto Ruins Experiment\n* Windurst Mission 1-2: The Heart of the Matter\n* Windurst Mission 6-2: Saintly Invitation\n* Windurst Mission 8-2: The Jester Who'd Be King\n* Windurst Mission 9-1: Doll of the Dead\n* Windurst Mission 9-2: Moon Reading\n* A Crystalline Prophecy (Mission)\n" },
    ['Aramu-Paramu']                     = { zones = { "Windurst", "Windurst Waters map = North|F-10" }, zoneIds = { 238 } },
