    ['Atagei-Portagei']                  = { type = "Special Event Coordinator", icon = "SpecialEventCoordinator.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nThis NPC was a Smilebringer for Starlight Celebration 2004, Starlight Celebration 2005, Starlight Celebration 2006, Starlight Celebration 2007, Starlight Celebration 2008 event." },
