    ['Baehu-Faehu']                      = { type = "Regional Merchant", icon = "RegionalVendor.png", zones = { "Windurst", "Windurst Waters map = North|G-5" }, zoneIds = { 238 }, note = "Notes:\n*  When Windurst does not have control of Sarutabaruta, says: Sorry-dorry, but I'm taking a breaky-wakey! (Or, as you'll be knowing, since control of Sarutabaruta was lost, I'm out of stock, so go on, get going!)?" },
    ['Baha Mannohl']                     = { zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 } },
    ['Bikho Ronpotteh']                  = { type = "Special Event", icon = "SpecialEventCoordinator.png", zones = { "Windurst", "Windurst Waters (North)" }, zoneIds = { 238 }, note = "Notes:\nOne of The Dark Lilies of the Harvest Festival event held each October since 2004. Bikho's Story: This...was a secret place... A place...that nobody knew... The purrrfect spot... An enchanted spot... So many fish... They would just jump.... onto the hook... To fill...my empty belly... To help..my strrruggling mother... I would fish...and fish...and fish... We were poor...I had no other choice... Even so...those days were fun... But I hated being poor... I delved...into forbidden magic... I'm sorry...Mother... The day...I left home... I wanted...wanted to tell you..." },
    ['Bin Stejihna']                     = { type = "Regional Vendor", icon = "RegionalVendor.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 } },
    ['Boizo-Naizo']                      = { type = "Riding the Clouds", icon = "QuestNPC.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Involved in Quests:\n* Riding on the Clouds\n" },
    ['Bonchacha']                        = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Notes:\nDialog: Professor Koru-Moru, the old minister who lives in that manor there, is more famous for being the local ding-a-ling than for serving as the School of Magic's principal! I just know he's up to something in there! I came over to call in and have a little chitchat, but it seems as if he is, how shall we say...otherwise occupied...?" },
