    ['Ghantata, W.W.']                   = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Windurst", "Yhoator Jungle" }, zoneIds = { 124 }, note = "Notes:\nAppears, when Elshimo Uplands is under weekly conquest-control by Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Elshimo Uplands Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer." },
    ['Gioh Ajihri']                      = { type = "Quest Giver", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Starts Quests:\n* Twinstone Bonding\n\nInvolved in Quests:\n* Lost Chick\n* Fire and Brimstone (optional)" },
    ['Gordias']                          = { type = "Flavor NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Waters map = North|F-9" }, zoneIds = { 238 }, note = "Notes:\nDialog: \"Ahhh, I'm sooo full! I just ate ten servings! Hahaha... Are you impressed? Well, that there resturant sells only Tarutaru-sized servings. Ten servings is quite an easy amount to stomach.\"" },
    ['Gottah Maporushanoh']              = { type = "Quest Associate", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Involved in Quests:\n* Lost Chick" },
    ['Guwanana']                         = { type = "Harvest Festival", icon = "Event.png", zones = { "Windurst", "Windurst Waters (South)" }, zoneIds = { 238 }, note = "Notes:\nOne of The Dark Lilies of the Harvest Festival event, held each October since 2004. Guwanana's Story: Glimmer...shimmer... Shimmer...glimmer... Little fishies... Shimmering fishy-wishes... Where have you all gone...? Little fishies... Glimmering fishy-wishies... Are you here...? You mustaru be hiding... Here and there... The fishy-wishies I let free... Shimmering... glimmering...fish... But...I don'taru see you...? Where have you gone...? The same as before... Nowhere to be found... But wait... That shimmer-glimmering... The Flash spell fused into your scaly-wales... Glimmer...shimmer... So many little fishy-wishies... You survived..." },
    ['Haah Chakaila']                    = { zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 } },
    ['Hae Jakkya']                       = { type = "Quest Associate", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Involved in Quests:\n* Chasing Tales" },
    ['Hakaru-Marikaru']                  = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nDialog: Elvaan are all so high and haughty. It almost seems like they look down at us Tarutaru at times. Huh...? How dare you say that's because we are so short that everyone can't help but look down at us! Beat it before I bite your kneecaps!" },
    ['Hakeem']                           = { type = "Advanced Synthesis Support", icon = "GuildMaster.png", zones = { "Windurst", "Windurst Waters map = North|D-9" }, zoneIds = { 238 } },
    ['Harara, W.W.']                     = { type = "Conquest Overseer", icon = "ConquestOverseer.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nMain Conquest related NPC for Windurst citizens ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Windurst Mission-Rank bar (the red bar at the character's profile) :*Sells items for Conquest Points (Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations (Items for Bastok / Items for San d'Oria) at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Starts Supply Run Missions and offers a list of already delivered supplies :*Starts an Expeditionary Force by giving an E.F. region insignia to you :*Explains the Conquest system by choosing some available questions. ;Notes for characters only without Windurst as current Allegiance: :*Doesn't offer any function For further information see Conquest Overseer." },
    ['Hariga-Origa']                     = { type = "Quest Giver", icon = "QuestGiver.png", zones = { "Windurst", "Windurst Waters map = North|F-8, Optistery" }, zoneIds = { 238 }, note = "Starts Quests:\n* Glyph Hanger\n* A Smudge on One's Record" },
    ['Hauh Colphioh']                    = { type = "Guild Points", icon = "GuildworkersUnionRepresentative.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nHauh Colphioh is in charge of the Guildworker's Union for clothcrafting in Windurst. Once you have attained at least level 28 Cloftcraft you may speak with her, and begin accumulating Guild Points for items you turn in. The item requested changes daily, so its important to check back with her to keep track of current time limits, and to find out what new items the guild is accepting." },
