    ['Istvan']                           = { type = "ENM Timer", icon = "Dialogue.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\n* Provides information on ENM battlefield lockout." },
    ['Iya Rihyo']                        = { type = "Starlight Event", icon = "Event.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nCounts a a child for Starlight Celebration 2008 Dialog: Those automation guards called Cardians are said to grrrow smarter and smarter by the day as they learrrn more and more. It's only a matter of time until they all start developing their own perrrsonalities and then begin to fight among themselves. Won't that be fun?" },
    ['Jack of Diamonds']                 = { type = "Adventurer's Assistant", icon = "AdventurersAssistant.png", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Notes:\nOffers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*\"To show you a map of Windurst.\": [Displays an overview map of Windurst] :*\"How to give items to townsfolk.\": Interchange of items and money between people and things is called \"Trading.\" First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press \"Trade\" button. Next choose items to hand over! Press \"Confirm\" button! Targeted entity should receive items. :*\"How to go outside and battle.\": Before setting out to battle: Confirm equipment is properly equipped! Magic-users \"Use\" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: \"Check\" monster to confirm its strength! After battle is won: Look for \"Spoils\" dropped by monsters. If in party, \"Cast Lots\" for spoils! :*\"About quests and missions.\": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town's gatehouse. :*\"Nothing in particular.\": Feel free to ask next time you need Jack's help. Over and out!" },
    ['Jack of Hearts']                   = { type = "Adventurer's Assistant", icon = "AdventurersAssistant.png", zones = { "Windurst", "Windurst Waters map = North|G-9" }, zoneIds = { 238 }, note = "Notes:\nOffers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*\"To show you a map of Windurst.\": [Displays an overview map of Windurst] :*\"How to give items to townsfolk.\": Interchange of items and money between people and things is called \"Trading.\" First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press \"Trade\" button. Next choose items to hand over! Press \"Confirm\" button! Targeted entity should receive items. :*\"How to go outside and battle.\": Before setting out to battle: Confirm equipment is properly equipped! Magic-users \"Use\" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: \"Check\" monster to confirm its strength! After battle is won: Look for \"Spoils\" dropped by monsters. If in party, \"Cast Lots\" for spoils! :*\"About quests and missions.\": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town's gatehouse. :*\"Nothing in particular.\": Feel free to ask next time you need Jack's help. Over and out!" },
    ['Jack of Spades']                   = { type = "Adventurer's Assistant", icon = "AdventurersAssistant.png", zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 }, note = "Notes:\nCan be traded Adventurer Coupon for those starting in Windurst Woods. Offers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*\"To show you a map of Windurst.\": [Displays an overview map of Windurst] :*\"How to give items to townsfolk.\": Interchange of items and money between people and things is called \"Trading.\" First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press \"Trade\" button. Next choose items to hand over! Press \"Confirm\" button! Targeted entity should receive items. :*\"How to go outside and battle.\": Before setting out to battle: Confirm equipment is properly equipped! Magic-users \"Use\" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: \"Check\" monster to confirm its strength! After battle is won: Look for \"Spoils\" dropped by monsters. If in party, \"Cast Lots\" for spoils! :*\"About quests and missions.\": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town's gatehouse. :*\"Nothing in particular.\": Feel free to ask next time you need Jack's help. Over and out!" },
