    ['Luuh Koplehn']                     = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Notes:\nDialog: Come on, Professorrr Koru-Moru. I'm not moving until you cough up the gil forrr yourrr overdue accounts at the Bonework's Guild. As both a ministerrr and the principal of our local school, shouldn't you be setting a betterrr example?" },
