    ['Machitata']                        = { type = "Residence Renter", icon = "RoomRenters.png", zones = { "Windurst", "Windurst Waters map = North|L-11" }, zoneIds = { 238 }, note = "Involved in Quests:\n* Hat in Hand" },
    ['Mahoh Mahborogho']                 = { zones = { "Windurst", "Windurst Woods" }, zoneIds = { 241 } },
    ['Majiji']                           = { zones = { "Windurst", "Windurst Waters map = North|K-6" }, zoneIds = { 238 } },
    ['Malmi-Monmi']                      = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Notes:\nDialog: Windurst Walls is the coolest-woolest place. Not only do we have Heavens Tower and a consulate, but all the ex-ministers have manors here! When the ministers of the five magic ministries of Windurst retire, they gain the title of doctor or professor, and are allowed to live in special-wecial houses so they can continue their studies without worries." },
