    ['Pakeke']                           = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Walls" }, zoneIds = { 239 }, note = "Notes:\nDialog: Welcome to the magical town of Windurst. Home of fun-loving Tarutaru and free-willed Mithra. You are now in Windurst Walls. It's a holy site revered by us Tarutaru since ancientaru times. I hope you enjoy your visitaru here." },
