    ['Shanana']                          = { type = "Dialogue NPC", icon = "Dialogue.png", zones = { "Windurst", "Windurst Waters map = North|G-11" }, zoneIds = { 238 }, note = "Notes:\nOnce in several hundred years, a great wizard is born out of the Tarutaru in Windurst. This wizard is so powerful, he is called the Mastermind of the Millen[n]ium. Decades ago, a child formidable enough to carry that title graduated at the top of his class from the School of Magic. I'm sure you'll hear his name mentioned as the hero who saved Windurst." },
